"""Small number helpers."""


def mean(values: list[float]) -> float:
    """The average of ``values``."""
    return sum(values) / len(values)


def clamp(value: float, low: float, high: float) -> float:
    """``value`` limited to the range ``low`` to ``high``."""
    if low > high:
        raise ValueError(f"low {low} is greater than high {high}")
    return max(low, min(value, high))

import unittest

from mathkit import clamp, mean


class MeanTest(unittest.TestCase):
    def test_mean(self) -> None:
        self.assertEqual(mean([1, 2, 3]), 2)


class ClampTest(unittest.TestCase):
    def test_inside_and_outside(self) -> None:
        self.assertEqual(clamp(5, 0, 10), 5)
        self.assertEqual(clamp(-1, 0, 10), 0)
        self.assertEqual(clamp(11, 0, 10), 10)

    def test_low_above_high(self) -> None:
        with self.assertRaises(ValueError):
            clamp(1, 10, 0)


if __name__ == "__main__":
    unittest.main()
